    "knowledge": "Sensitivity Weight Values",
    "description": "Numerical weights for sensitivity calculations",
    "definition": "EnvSensitivity: Low=1, Medium=5, High=10; LightSensitivity: Low=1, Medium=5, High=10; TempSensitivity: Low=1, Medium=5, High=10; HumiditySensitivity: Low=1, Medium=5, High=10"
  },
  {
    "id": 2,
    "knowledge": "Environmental Risk Factor (ERF)",
    "description": "Quantifies the overall environmental risk to an artifact based on its sensitivities.",
    "definition": "ERF = \\frac{\\sum_{i \\in sensitivities} SensWeight_i}{|sensitivities|}, \\text{where sensitivities includes EnvSensitivity, LightSensitivity, TempSensitivity, etc, with value mapping based on Sensitivity Weight Values.}"
  },
  {
    "id": 3,
    "knowledge": "Artifact Vulnerability Score (AVS)",
    "description": "Comprehensive score indicating how vulnerable an artifact is based on its conservation priority and environmental sensitivities.",
    "definition": "AVS = CPI \\times ERF, \\text{where higher scores indicate artifacts requiring more urgent attention}"
  },
  {
    "id": 4,
    "knowledge": "Display Safety Duration (DSD)",
    "description": "Calculates the recommended maximum display duration for an artifact based on its sensitivities.",
    "definition": "DSD = \\frac{BaseDuration \\times (10 - LightSensWeight) \\times (10 - TempSensWeight) \\times (10 - HumidSensWeight)}{1000}, \\text{where BaseDuration=36 months, and SensWeight uses Sensitivity Weight Values.}"
  },
  {
    "id": 5,
    "knowledge": "Showcase Environmental Stability Rating (SESR)",
    "description": "Measures how well a showcase maintains stable environmental conditions.",
    "definition": "SESR = 10 - \\frac{(TempVar24h + \\frac{HumVar24h}{5} + LeakRate)}{3}, \\text{where higher scores indicate more stable showcases}"
  },
  {
    "id": 6,
    "knowledge": "Artifact Exhibition Compatibility (AEC)",
    "description": "Determines how compatible an artifact is with its current showcase environment.",
    "definition": "AEC = 10 - |ERF - SESR|, \\text{where a score closer to 10 indicates better compatibility}"
  },
  {
    "id": 7,
    "knowledge": "Material Deterioration Rate (MDR)",
    "description": "Estimates the rate of material deterioration based on environmental factors.",
    "definition": "MDR = \\frac{ArtAgeYears \\times ERF \\times (RelHumidity - 50)^2 \\times TempC}{100000}, \\text{where higher values indicate faster deterioration}"
  },
  {
    "id": 8,
    "knowledge": "Light Exposure Risk (LER)",
    "description": "Quantifies the risk from light exposure based on artifact sensitivity and current light levels.",
    "definition": "LER = \\frac{LightLux \\times LightSensWeight \\times VisibleExpLxh}{1000}, \\text{where LightSensWeight uses Sensitivity Weight Values}"
  },
  {
    "id": 9,
    "knowledge": "Conservation Budget Efficiency (CBE)",
    "description": "Measures the efficiency of conservation budget allocation relative to artifact importance.",
    "definition": "CBE = \\frac{\\sum_{i \\in artifacts} (CPI_i \\times BudgetRatio_i)}{|artifacts|}, \\text{where BudgetRatio is the proportion of total conservation budget allocated to each artifact}"
  },
  {
    "id": 10,
    "knowledge": "Visitor Impact Risk (VIR)",
    "description": "Assesses the risk posed by visitor traffic to artifacts in exhibition halls.",
    "definition": "VIR = \\frac{VisitorCountDaily \\times VisitorFlowRate \\times VisitorDwellMin}{1000}, \\text{where VisitorFlowRate is numerically mapped: Low=1, Medium=3, High=5}"
  },
  {
    "id": 11,
    "knowledge": "High-Value Artifact",
    "description": "Identifies artifacts with exceptional historical, cultural, or monetary value requiring special attention.",
    "definition": "An artifact is considered high-value when its InsValueUSD exceeds $1,000,000 OR when both HistSignRating and CultScore are in the top 10% of all artifacts."
  },
  {
    "id": 12,
    "knowledge": "Conservation Emergency",
    "description": "Identifies artifacts requiring immediate conservation intervention.",
    "definition": "A situation where an artifact has ConserveStatus='Critical' AND a TreatPriority='Urgent'."
  },
  {
    "id": 13,
    "knowledge": "Environmental Instability Event",
    "description": "Identifies periods when showcase environmental conditions fluctuate beyond acceptable parameters.",
    "definition": "Occurs when TempVar24h > 1\u00b0C OR HumVar24h > 3 within a 24-hour period."
  },
  {
    "id": 14,
    "knowledge": "Accelerated Deterioration Scenario",
    "description": "Identifies conditions that could lead to rapid artifact deterioration.",
    "definition": "Occurs when MDR > 5 AND at least two SensitivityData values are 'High'."
  },
  {
    "id": 15,
    "knowledge": "Exhibition Rotation Candidate",
    "description": "Identifies artifacts that should be considered for rotation out of display.",
    "definition": "An artifact is a rotation candidate when its current display duration exceeds 75% of its DSD OR LER > 7."
  },
  {
    "id": 16,
    "knowledge": "Showcase Failure Risk",
    "description": "Identifies showcases at risk of failing to maintain proper environmental conditions.",
    "definition": "Occurs when SESR < 4 OR at least three of the following are true: SealCondition='Poor', MaintStatus='Overdue', FilterStatus='Replace Now', SilicaGelStatus='Replace Now'."
  },
  {
    "id": 17,
    "knowledge": "Conservation Budget Crisis",
    "description": "Identifies when conservation budget allocation is insufficient for high-priority artifacts.",
    "definition": "Occurs when CBE < 0.5 AND at least one artifact has ConserveStatus='Critical' and BudgetAllocStatus='Insufficient'."
  },
  {
    "id": 18,
    "knowledge": "Dynasty Value Artifact",
    "description": "Identifies artifacts from historically significant dynasties with higher research and cultural value.",
    "definition": "Artifacts from 'Ming', 'Han', or 'Tang' dynasties that also have ResearchValRating > 8."
  },
  {
    "id": 19,
    "knowledge": "Visitor Crowd Risk",
    "description": "Identifies exhibition halls where high visitor numbers pose risks to artifact safety.",
    "definition": "Occurs when VIR > 5 AND SecLevel='Level 1' for any artifact in the hall."
  },
  {
    "id": 20,
    "knowledge": "Organic Material Vulnerability",
    "description": "Identifies organic materials requiring special environmental conditions.",
    "definition": "Artifacts with MatType='Wood', 'Textile', or 'Paper' AND EnvSensitivity='High' require specialized environmental controls with narrower humidity and temperature ranges than inorganic materials."
  },
  {
    "id": 21,
    "knowledge": "ArtifactsCore.ConserveStatus",
    "description": "Illustrates the conservation status values and their meanings.",
    "definition": "Values range from 'Excellent' (recently conserved, no issues), 'Good' (stable with minor issues), 'Fair' (stable but with noticeable issues), 'Poor' (active deterioration), to 'Critical' (severe deterioration requiring immediate intervention)."
  },
  {
    "id": 22,
    "knowledge": "ArtifactRatings.HistSignRating",
    "description": "Illustrates the historical significance rating scale.",
    "definition": "A SMALLINT typically ranging from 1-10, where 1-3 indicates minor historical significance, 4-7 indicates moderate significance, and 8-10 indicates exceptional historical importance that fundamentally contributes to our understanding of past cultures or events."
  },
  {
    "id": 23,
    "knowledge": "SensitivityData.LightSensitivity",
    "description": "Illustrates light sensitivity classifications and their implications.",
    "definition": "Values include 'Low' (can tolerate up to 300 lux, like stone artifacts), 'Medium' (should be limited to 150-200 lux, like oil paintings), and 'High' (restricted to 50 lux or less, like textiles and works on paper)."
  },
  {
    "id": 24,
    "knowledge": "SensitivityData.HumiditySensitivity",
    "description": "Illustrates humidity sensitivity classifications and their implications.",
    "definition": "Values include 'Low' (can tolerate 30-65% RH, like stone artifacts), 'Medium' (requires 40-60% RH, like wood), and 'High' (requires 45-55% RH with minimal fluctuation, like lacquer work)."
  },
  {
    "id": 25,
    "knowledge": "ExhibitionHalls.CCTVCoverage",
    "description": "Illustrates CCTV coverage classifications.",
    "definition": "'Full' indicates 100% exhibition space coverage with overlapping cameras, 'Partial' indicates 60-90% coverage with possible blind spots, and 'Limited' indicates less than 60% coverage focusing only on high-value areas."
  },
  {
    "id": 26,
    "knowledge": "Showcases.Airtightness",
    "description": "Illustrates showcase airtightness measurement.",
    "definition": "A REAL value typically ranging from 0.01 (extremely airtight, less than 0.01 air changes per day) to 5.0 (poor airtightness, multiple air changes per day). Museum-grade showcases typically maintain values below 0.1."
  },
  {
    "id": 27,
    "knowledge": "EnvironmentalReadingsCore.TempC",
    "description": "Illustrates temperature readings and their conservation implications.",
    "definition": "Values typically range from 15-25\u00b0C, with 18-22\u00b0C being ideal for most collections. Fluctuations greater than 2\u00b0C within 24 hours can stress materials. Values outside 10-30\u00b0C indicate environmental control failure requiring immediate attention."
  },
  {
    "id": 28,
    "knowledge": "EnvironmentalReadingsCore.RelHumidity",
    "description": "Illustrates relative humidity readings and their conservation implications.",
    "definition": "Values typically range from 30-65%, with 45-55% being ideal for mixed collections. Fluctuations greater than 5% within 24 hours can cause dimensional changes in organic materials. Values below 30% risk embrittlement, while above 65% risk mold growth."
  },
  {
    "id": 29,
    "knowledge": "LightAndRadiationReadings.LightLux",
    "description": "Illustrates light intensity measurements and their conservation implications.",
    "definition": "Values in lux range from near-dark (5-10 lux) to typical indoor lighting (300-500 lux). Conservation standards recommend 50 lux for highly sensitive materials, 150-200 lux for paintings and wood, and up to 300 lux for stone and metal. Daylight can exceed 10,000 lux and should be filtered."
  },
  {
    "id": 31,
    "knowledge": "Total Environmental Threat Level (TETL)",
    "description": "Comprehensive measurement of all environmental threats to an artifact based on multiple risk factors.",
    "definition": "TETL = ERF + LER + (MDR \u00d7 2), where ERF is the Environmental Risk Factor, LER is the Light Exposure Risk, and MDR is the Material Deterioration Rat."
  },
  {
    "id": 32,
    "knowledge": "Showcase Protection Adequacy (SPA)",
    "description": "Measures how well a showcase protects its artifacts based on its stability and the artifacts' requirements.",
    "definition": "SPA = SESR - (ERF \u00d7 0.5), where SESR is the Showcase Environmental Stability Rating and ERF is the Environmental Risk Factor. Positive values indicate adequate protection."
  },
  {
    "id": 33,
    "knowledge": "Conservation Backlog Risk (CBR)",
    "description": "Quantifies the risk associated with delayed conservation treatments.",
    "definition": "CBR = (CPI \u00d7 (Days since LastCleaningDate - CleanIntervalDays)) \u00f7 100, where CPI is the Conservation Priority Index. Higher values indicate higher risk from delayed conservation."
  },
  {
    "id": 34,
    "knowledge": "Visitor Capacity Safety Factor (VCSF)",
    "description": "Determines the safe visitor capacity for exhibition halls containing sensitive artifacts.",
    "definition": "VCSF = VIR \u00f7 (AVS \u00d7 0.1), where VIR is the Visitor Impact Risk and AVS is the Artifact Vulnerability Score. Lower values indicate safer visitor capacities."
  },
  {
    "id": 35,
    "knowledge": "Exhibition Safety Quotient (ESQ)",
    "description": "Comprehensive safety rating for an exhibition based on artifacts, showcases, and visitor factors.",
    "definition": "ESQ = ((10 - AVS) + AEC + (10 - VIR)) \u00f7 3, where AVS is the Artifact Vulnerability Score, AEC is the Artifact Exhibition Compatibility, and VIR is the Visitor Impact Risk. Higher values indicate safer exhibitions."
  },
  {
    "id": 36,
    "knowledge": "Conservation Resource Allocation Efficiency (CRAE)",
    "description": "Measures how efficiently conservation resources are allocated based on priorities and budget.",
    "definition": "CRAE = CBE \u00d7 (1 - (CBR \u00f7 10)), where CBE is the Conservation Budget Efficiency and CBR is the Conservation Backlog Risk. Higher values indicate more efficient resource allocation."
  },
  {
    "id": 37,
    "knowledge": "Material Aging Projection (MAP)",
    "description": "Projects the rate of artifact aging based on material type and environmental conditions.",
    "definition": "MAP = MDR \u00d7 (1 + (TETL \u00f7 20)), where MDR is the Material Deterioration Rate and TETL is the Total Environmental Threat Level. Higher values indicate faster projected aging."
  },
  {
    "id": 38,
    "knowledge": "Exhibition Rotation Priority Score (ERPS)",
    "description": "Calculates priority for rotating artifacts in and out of exhibition based on multiple factors.",
    "definition": "ERPS = (DSD - DisplayDurMonths) \u00d7 (LER + 1) \u00d7 (CPI + 1) \u00f7 100, where DSD is the Display Safety Duration, LER is the Light Exposure Risk, and CPI is the Conservation Priority Index. Lower values indicate higher rotation priority."
  },
  {
    "id": 39,
    "knowledge": "Environmental Compliance Index (ECI)",
    "description": "Measures how well current environmental conditions meet the requirements for an artifact.",
    "definition": "ECI = 10 - (|(TempC - IdealTemp)| + |(RelHumidity - IdealHumidity)| \u00f7 5 + ERF \u00f7 2), where ERF is the Environmental Risk Factor. Higher values indicate better compliance with requirements."
  },
  {
    "id": 40,
    "knowledge": "Security Risk Exposure (SRE)",
    "description": "Quantifies an artifact's exposure to security risks based on value and security measures.",
    "definition": "SRE = (InsValueUSD \u00f7 100000) \u00d7 (10 - VIR) \u00f7 10, where VIR is the Visitor Impact Risk. Higher values indicate greater security risk exposure."
  },
  {
    "id": 41,
    "knowledge": "Critical Conservation Alert",
    "description": "Identifies artifacts in critical condition requiring immediate intervention.",
    "definition": "An artifact that meets both the Conservation Emergency criteria AND has an AVS > 8."
  },
  {
    "id": 42,
    "knowledge": "High Deterioration Risk Artifact",
    "description": "Identifies artifacts at high risk of rapid deterioration due to environmental factors.",
    "definition": "An artifact that has TETL > 15 AND falls under the Accelerated Deterioration Scenario."
  },
  {
    "id": 43,
    "knowledge": "Exhibition Rotation Urgency",
    "description": "Identifies artifacts that should be immediately removed from exhibition.",
    "definition": "Occurs when an artifact is an Exhibition Rotation Candidate AND has an ERPS < 0."
  },
  {
    "id": 44,
    "knowledge": "Showcase Compatibility Issue",
    "description": "Identifies incompatible artifact-showcase pairings requiring adjustment.",
    "definition": "Occurs when SPA < 0 AND the artifact is classified as having High-Value."
  },
  {
    "id": 45,
    "knowledge": "Conservation Resource Crisis",
    "description": "Identifies serious conservation resource allocation problems.",
    "definition": "Occurs when CRAE < 0.3 AND there is a Conservation Budget Crisis."
  },
  {
    "id": 46,
    "knowledge": "Dynasty Artifact at Risk",
    "description": "Identifies historically significant dynasty artifacts at conservation risk.",
    "definition": "An artifact that qualifies as a Dynasty Value Artifact AND has a MAP > 3."
  },
  {
    "id": 47,
    "knowledge": "Environmental Control Failure",
    "description": "Identifies situations where environmental controls are failing to protect artifacts.",
    "definition": "Occurs when ECI < 4 AND there is an Environmental Instability Event."
  },
  {
    "id": 48,
    "knowledge": "High Security Priority Artifact",
    "description": "Identifies artifacts requiring enhanced security measures.",
    "definition": "An artifact that is classified as High-Value AND has an SRE > 5."
  },
  {
    "id": 49,
    "knowledge": "Visitor Traffic Safety Concern",
    "description": "Identifies situations where visitor traffic poses safety concerns for exhibitions.",
    "definition": "Occurs when VCSF > 2 AND there is a Visitor Crowd Risk situation."
  },
  {
    "id": 50,
    "knowledge": "Organic Material Emergency",
    "description": "Identifies emergency situations for organic materials.",
    "definition": "Occurs when an artifact falls under the Organic Material Vulnerability classification AND has a TETL > 12."
  },
  {
    "id": 51,
    "knowledge": "High-Value Category",
    "description": "Classification system for categorizing high-value artifacts based on their monetary or cultural/historical significance.",
    "definition": "An artifact falls into 'Monetary High-Value' category when its InsValueUSD exceeds $1,000,000. It qualifies as 'Cultural/Historical High-Value' when both its HistSignRating and CultScore are in the top 10% of all artifacts (percentile rank = 1). Otherwise 'Other'."
  },
  {
    "id": 52,
    "knowledge": "ERPS Decision Threshold",
    "description": "Converts ERPS scores into conservation actions",
    "definition": "When ERPS < 0, trigger 'Immediate Rotation'; otherwise 'Monitor'."
  },
  {
    "id": 53,
    "knowledge": "Light Exposure Thresholds",
    "description": "Defines maximum safe light exposure levels for artifacts based on material sensitivity",
    "definition": "High sensitivity artifacts (textiles, paper) must not exceed 50 lux; Medium sensitivity (paintings, wood) must not exceed 200 lux. Based on conservation research about light-induced deterioration rates."
  },
  {
    "id": 54,
    "knowledge": "Conservation Environment Chronology (CEC)",
    "description": "A methodological approach used in museum conservation to segment environmental monitoring data into chronological intervals. This approach enables curators to identify seasonal trends, long-term shifts, and anomalies in environmental conditions that can affect artifact stability and preservation.",
    "definition": "CEC involves grouping readings (e.g., temperature, humidity, air pressure) by fixed time intervals (such as by year) to discern patterns and inform conservation strategies."
  },
  {
    "id": 55,
    "knowledge": "Artifact Rarity & Valuation (ARV)",
    "description": "Establishes criteria for identifying artifacts of exceptional rarity and valuation that demand heightened preservation measures and limited public access.",
    "definition": "Artifacts are categorized as ARV if their insurance value exceed $1,000,000."
  },
  {
    "id": 56,
    "knowledge": "Conservation Priority Level",
    "description": "Classifies artifacts into priority levels based on their CPI scores",
    "definition": "'High Priority': CPI > 7 (Artifacts requiring immediate conservation attention); 'Medium Priority': 4 < CPI \u2264 7 (Artifacts needing monitoring and planned conservation); 'Low Priority': CPI \u2264 4 (Artifacts in stable condition)."
  }
]

